+
+static int width, height, pass;
+static unsigned int sceneSeed;
+static std::vector<Vec> accumulation;
+static std::vector<unsigned char> pixels;
+extern "C" {
+void init_scene(int w, int h, unsigned int seed) {
+  width=w; height=h; pass=0; sceneSeed=seed;
+  accumulation.assign(w*h, Vec()); pixels.assign(w*h*4, 0);
+}
+void set_color(int id, double r, double g, double b) {
+  if(id>=0 && id<8) spheres[id].c=Vec(r,g,b);
+}
+unsigned char* pixel_buffer() { return pixels.data(); }
+void render_rows(int start, int count) {
+  Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm());
+  Vec cx=Vec(width*.5135/height), cy=(cx%cam.d).norm()*.5135;
+  for(int y=start;y<start+count && y<height;y++) {
+    uint32_t state=sceneSeed + y*9781u + pass*6271u;
+    unsigned short Xi[3]={(unsigned short)state,(unsigned short)(state>>16),(unsigned short)(y*y*y+pass*7919)};
+    for(int x=0;x<width;x++) {
+      int i=(height-y-1)*width+x;
+      Vec sample;
+      for(int sy=0;sy<2;sy++) for(int sx=0;sx<2;sx++) {
+        double r1=2*erand48(Xi), dx=r1<1?sqrt(r1)-1:1-sqrt(2-r1);
+        double r2=2*erand48(Xi), dy=r2<1?sqrt(r2)-1:1-sqrt(2-r2);
+        Vec d=cx*(((sx+.5+dx)/2+x)/width-.5)+cy*(((sy+.5+dy)/2+y)/height-.5)+cam.d;
+        sample=sample+radiance(Ray(cam.o+d*140,d.norm()),0,Xi)*.25;
+      }
+      accumulation[i]=accumulation[i]+sample;
+      Vec c=accumulation[i]*(1.0/(pass+1));
+      pixels[i*4]=toInt(c.x); pixels[i*4+1]=toInt(c.y); pixels[i*4+2]=toInt(c.z); pixels[i*4+3]=255;
+    }
+  }
+  if(start+count>=height) pass++;
+}
+}
+#ifdef NATIVE_PREVIEW
+int main() {
+  init_scene(720,480,42);
+  for(int p=0;p<32;p++) render_rows(0,480);
+  FILE* f=fopen("/tmp/smallpt-preview.rgb","wb");
+  fwrite(pixels.data(),1,pixels.size(),f); fclose(f);
+}
+#endif
