+    radiance(reflRay,depth,Xi)*RP:radiance(Ray(x,tdir),depth,Xi)*TP) :
+    radiance(reflRay,depth,Xi)*Re+radiance(Ray(x,tdir),depth,Xi)*Tr);
+}
+
+// A progressive, single-threaded API for the browser worker. Each pass traces
+// the original 2x2 tent-filtered subpixels (four samples per pixel).
+static int width, height;
+static uint32_t seed;
+static std::vector<Vec> accumulation;
+static std::vector<unsigned char> pixels;
+extern "C" {
+unsigned char* init_scene(int w, int h, unsigned int render_seed) {
+  width = w; height = h; seed = render_seed;
+  accumulation.assign(w*h, Vec()); pixels.assign(w*h*4, 0);
+  spheres[0].c = Vec(.75,.28,.20);
+  spheres[1].c = Vec(.30,.55,.38);
+  spheres[6].c = spheres[7].c = Vec(.999,.999,.999);
+  return pixels.data();
+}
+void set_color(int id, double r, double g, double b) {
+  if (id >= 0 && id < 8) spheres[id].c = Vec(r,g,b);
+}
+void render_rows(int first, int count, int pass) {
+  Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm());
+  Vec cx=Vec(width*.5135/height), cy=(cx%cam.d).norm()*.5135;
+  for (int row=first; row<first+count && row<height; row++) {
+    int y=height-row-1;
+    uint32_t state=seed ^ (uint32_t(y+1)*747796405u) ^ (uint32_t(pass+1)*2891336453u);
+    unsigned short Xi[3]={(unsigned short)state,(unsigned short)(state>>16),(unsigned short)(y*y*y+pass*71)};
+    for (int x=0; x<width; x++) {
+      Vec result;
+      for(int sy=0;sy<2;sy++) for(int sx=0;sx<2;sx++) {
+        double r1=2*erand48(Xi), dx=r1<1?sqrt(r1)-1:1-sqrt(2-r1);
+        double r2=2*erand48(Xi), dy=r2<1?sqrt(r2)-1:1-sqrt(2-r2);
+        Vec d=cx*(((sx+.5+dx)/2+x)/width-.5)+cy*(((sy+.5+dy)/2+y)/height-.5)+cam.d;
+        result=result+radiance(Ray(cam.o+d*140,d.norm()),0,Xi)*.25;
+      }
+      int i=row*width+x;
+      accumulation[i]=accumulation[i]+result;
+      Vec c=accumulation[i]*(1./(pass+1));
+      pixels[4*i]=toInt(c.x); pixels[4*i+1]=toInt(c.y); pixels[4*i+2]=toInt(c.z); pixels[4*i+3]=255;
+    }
+  }
+}
+}
+#ifdef SMALLPT_PREVIEW
+int main() {
+  init_scene(640,480,42);
+  for(int pass=0;pass<32;pass++) render_rows(0,480,pass);
+  FILE* f=fopen("/tmp/smallpt-preview.ppm","wb");
+  fprintf(f,"P6\n640 480\n255\n");
+  for(int i=0;i<640*480;i++) fwrite(&pixels[i*4],1,3,f);
+  fclose(f);
+}
+#endif
