+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { createSigner, importVerificationKey, signArtifact, verifyArtifact } from '../signatures.mjs';
+const details = { type: 'receipt', description: 'Maple Oat Latte × 1', amountCents: 550 };
+const serialize = document => JSON.stringify(document);
+const supportedSuites = ['Ed25519', 'ECDSA'];
+if (globalThis.SubtleCrypto?.supports?.('sign', 'ML-DSA-65')) supportedSuites.push('ML-DSA-65');
+for (const suite of supportedSuites) {
+  test(`${suite}: authentic receipts and vouchers survive export/import; tampering fails`, async () => {
+    const signer = await createSigner(suite);
+    assert.equal(signer.keys.privateKey.extractable, false);
+    const trusted = await importVerificationKey(serialize(signer.verificationKey));
+    const receipt = await signArtifact(signer, details);
+    assert.equal((await verifyArtifact(serialize(receipt), trusted)).payload.amountCents, 550);
+    const changed = structuredClone(receipt);
+    const payload = JSON.parse(changed.payload);
+    payload.amountCents = 1;
+    changed.payload = serialize(payload);
+    await assert.rejects(verifyArtifact(serialize(changed), trusted), /Signature invalid/);
+    payload.type = 'voucher';
+    payload.expiresAt = '2099-12-31T23:59:59.999Z';
+    changed.payload = serialize(payload);
+    await assert.rejects(verifyArtifact(serialize(changed), trusted), /Signature invalid/);
+    const voucher = await signArtifact(signer, { ...details, type: 'voucher', expiresAt: '2099-12-31T23:59:59.999Z' });
+    assert.equal((await verifyArtifact(serialize(voucher), trusted)).expired, false);
+    assert.equal((await verifyArtifact(serialize(voucher), trusted, Date.parse('2100-01-01'))).expired, true);
+    const attacker = await createSigner(suite);
+    const forged = await signArtifact(attacker, details);
+    await assert.rejects(verifyArtifact(serialize(forged), trusted), /trusted key/);
+    forged.keyId = trusted.keyId;
+    await assert.rejects(verifyArtifact(serialize(forged), trusted), /Signature invalid/);
+    const corrupted = { ...receipt, signature: receipt.signature.slice(4) };
+    await assert.rejects(verifyArtifact(serialize(corrupted), trusted));
+    await assert.rejects(verifyArtifact(serialize(receipt), undefined), /trusted verification key/);
+    await assert.rejects(verifyArtifact('not json', trusted), /valid JSON/);
+    await assert.rejects(verifyArtifact('x'.repeat(64001), trusted), /too large/);
+    await assert.rejects(importVerificationKey(serialize({ ...signer.verificationKey, keyId: 'wrong' })), /fingerprint/);
+    await assert.rejects(signArtifact(signer, { ...details, amountCents: -1 }), /Invalid/);
+    await assert.rejects(signArtifact(signer, { ...details, amountCents: 1.1 }), /Invalid/);
+  });
+}
+test('automatic selection produces a working signature', async () => {
+  const signer = await createSigner();
+  const trusted = await importVerificationKey(serialize(signer.verificationKey));
+  const artifact = await signArtifact(signer, details);
+  assert.equal((await verifyArtifact(serialize(artifact), trusted)).payload.type, 'receipt');
+});

