+export default function SearchFlyout({ active }: { active: boolean }) {
+  const id = useId();
+  const [searchTerm, setSearchTerm] = useState('');
+  const [articles, setArticles] = useState<Article[] | null>(null);
+  const [error, setError] = useState('');
+
+  useEffect(() => {
+    if (!active || articles) return;
+    const controller = new AbortController();
+    setError('');
+    fetch(`${import.meta.env.BASE_URL}api/articles.json`, { signal: controller.signal })
+      .then(response => { if (!response.ok) throw new Error(); return response.json(); })
+      .then(setArticles)
+      .catch(error => { if (error.name !== 'AbortError') setError('Could not load articles. Close search and try again.'); });
+    return () => controller.abort();
+  }, [active, articles]);
+
+  const query = searchTerm.trim().toLowerCase();
+  const results = useMemo(() => (articles || []).filter(article =>
+    `${article.title} ${article.summary}`.toLowerCase().includes(query)
+  ), [articles, query]);
+  const visibleArticles = query ? results : (articles || []).slice(0, 3);
+
+  return <search>
+    <label htmlFor={id} className="block text-sm font-semibold text-gray-600 mb-2">Search for articles</label>
+    <input id={id} name="q" type="search" autoComplete="on" autoCapitalize="off" autoCorrect="off"
+      spellCheck={false} enterKeyHint="search" autoFocus
+      className="w-full p-2 border border-gray-300 rounded-md"
+      value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
+    <p role="status" className="text-sm text-gray-600 my-3">
+      {error || (!articles ? 'Loading articles…' : query ? `${results.length} results` : 'Featured articles')}
+    </p>
+    <ul className="space-y-2">
+      {visibleArticles.map(article => <li key={article.slug}>
+        <a href={`${import.meta.env.BASE_URL}articles/${article.slug}`} className="block hover:bg-gray-100 p-4 rounded-md">
+          <h3 className="font-bold text-lg text-gray-800">{article.title}</h3>
+          <p className="text-sm text-gray-600">{article.summary}</p>
+        </a>
+      </li>)}
+    </ul>
+  </search>;
 }
