+        signinForm.elements.password.value = '';
+        signinStatus.textContent = 'You are signed in.';
+      } catch {
+        signinStatus.textContent = 'Unable to sign in. Please check your credentials and try again.';
+      } finally {
+        signinButton.disabled = false;
+      }
+    });
+  </script>
