+
+type Modal = { type: 'add' | 'rename' | 'remove' | 'verify' | 'signin'; id?: string; name?: string };
+export default function AccountSettings() {
+  const [account, setAccount] = useState<Account | null>(null);
+  const [loading, setLoading] = useState(true);
+  const [supported, setSupported] = useState(false);
+  const [tab, setTab] = useState('Security');
+  const [modal, setModal] = useState<Modal | null>(null);
+  const [name, setName] = useState('');
+  const [password, setPassword] = useState('');
+  const [username, setUsername] = useState('');
+  const [busy, setBusy] = useState(false);
+  const [error, setError] = useState('');
+  const [message, setMessage] = useState('');
+  const [pending, setPending] = useState<Modal | null>(null);
+  const [openFaq, setOpenFaq] = useState<number | null>(0);
+  const [preference, setPreference] = useState(true);
+  const dialog = useRef<HTMLDialogElement>(null);
+  const base = import.meta.env.BASE_URL;
+  useEffect(() => { setSupported(supportsPasskeys()); api('session').then(d => setAccount(d.authenticated ? d.user : null)).catch(e => setError(errorMessage(e))).finally(() => setLoading(false)); const saved = localStorage.getItem('times-passkey-tips'); setPreference(saved !== 'false'); }, []);
+  useEffect(() => { if (modal) dialog.current?.showModal(); else dialog.current?.close(); }, [modal]);
+  function open(m: Modal) { setError(''); setPassword(''); setName(m.name || ''); setModal(m); }
+  function add() { open(account ? { type: 'add' } : { type: 'signin' }); }
+  async function run(action: () => Promise<any>, success: string, retry?: Modal) {
+    setBusy(true); setError(''); setMessage('');
+    try { const data = await action(); if (data.user) setAccount(data.user); setMessage(success); setModal(null); }
+    catch (e) { if (e instanceof AuthError && e.reauthenticate) { setPending(retry || (modal ? { ...modal, name: name || modal.name } : null)); open({ type: 'verify' }); } else setError(errorMessage(e)); }
+    finally { setBusy(false); }
+  }
+  async function verify(passkey: boolean) {
+    setBusy(true); setError('');
+    try { if (passkey) await authenticate(true); else await api('reauthenticate', { password }); setPassword(''); setName(pending?.name || ''); setModal(pending); setPending(null); }
+    catch (e) { setError(errorMessage(e)); } finally { setBusy(false); }
+  }
