@@ -0,0 +1,39 @@
+const form = document.getElementById('newsletter-form');
+const status = document.getElementById('newsletter-status');
+const button = form.querySelector('button');
+
+form.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  if (button.disabled) return;
+
+  button.disabled = true;
+  form.setAttribute('aria-busy', 'true');
+  status.textContent = 'Signing you up…';
+  const controller = new AbortController();
+  const timeout = setTimeout(() => controller.abort(), 10000);
+
+  try {
+    const response = await fetch('/api/newsletter', {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+      credentials: 'same-origin',
+      redirect: 'error',
+      signal: controller.signal,
+      body: JSON.stringify({
+        email: form.elements.email.value,
+        website: form.elements.website.value,
+      }),
+    });
+    if (!response.ok) throw new Error('Signup failed');
+    const result = await response.json();
+    if (result.ok !== true) throw new Error('Signup failed');
+    status.textContent = 'You’re on the list! Thanks for signing up for Daily Grind news.';
+    form.reset();
+  } catch {
+    status.textContent = 'We couldn’t send your signup. Please check your connection and try again. Your email is still here.';
+  } finally {
+    clearTimeout(timeout);
+    button.disabled = false;
+    form.removeAttribute('aria-busy');
+  }
+});
