+      font-weight: normal;
+      line-height: 1.6;
+      color: #3e2723;
+      background: white;
+      height: 100%;
+      padding: 20px;
+      border-radius: 8px;
+      box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
+      text-align: center;
+    }
+
+    h3 {
+      font-size: 1.17em;
+      margin-bottom: 10px;
+      color: #4e342e;
+    }
+
+    .badge {
+      display: inline-block;
+      margin-bottom: 10px;
+      padding: 2px 8px;
+      border-radius: 4px;
+      background: #ffab40;
+      font-size: 0.75em;
+      font-weight: bold;
+    }
+
+    .badge[hidden] {
+      display: none;
+    }
+
+    a {
+      display: inline-block;
+      background: #4e342e;
+      color: white;
+      padding: 10px 20px;
+      text-decoration: none;
+      border-radius: 5px;
+      margin-top: 15px;
+      transition: background 0.3s;
+    }
+
+    a:hover {
+      background: #3e2723;
+    }
+  </style>
+  <article aria-labelledby="title">
+    <span class="badge" hidden>Limited</span>
+    <h3 id="title"></h3>
+    <p></p>
+    <a></a>
+  </article>
+`;
+
+class SeasonalCard extends HTMLElement {
+  static observedAttributes = [
+    'drink-title', 'description', 'action-href', 'action-label', 'limited',
+  ];
+
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open' }).append(template.content.cloneNode(true));
+  }
+
+  connectedCallback() {
+    this.render();
+  }
+
+  attributeChangedCallback() {
+    this.render();
+  }
+
+  render() {
+    const root = this.shadowRoot;
+    root.querySelector('h3').textContent = this.getAttribute('drink-title') ?? '';
+    root.querySelector('p').textContent = this.getAttribute('description') ?? '';
+    const action = root.querySelector('a');
+    action.textContent = this.getAttribute('action-label') ?? 'View Details';
+    if (this.hasAttribute('action-href')) {
+      action.setAttribute('href', this.getAttribute('action-href'));
+    } else {
+      action.removeAttribute('href');
+    }
+    root.querySelector('.badge').hidden = !this.hasAttribute('limited');
+  }
+}
+
+customElements.define('seasonal-card', SeasonalCard);

