+  }
+
+  function restoreEnglish() {
+    revision++;
+    controller?.abort();
+    controller = undefined;
+    options = undefined;
+    show(originals, 'en');
+    select.value = 'en';
+    select.disabled = false;
+    button.disabled = true;
+    restore.disabled = true;
