eader"><div>{['Preview','Code'].map(t => <button key={t} className={tab === t ? 'active' : ''} onClick={() => setTab(t)}>{t === 'Preview' ? <Squares2X2Icon /> : <CodeBracketIcon />}{t}</button>)}</div><button className="copy-button" onClick={copy}><DocumentDuplicateIcon />Copy code</button></div><div className={`output-canvas ${tab === 'Code' ? 'code-canvas' : ''}`}>{tab === 'Code' ? <pre><code>{code}</code></pre> : <div className={`live-preview intent-${intent} variant-${variant.toLowerCase()} size-${size.toLowerCase()} ${!showIcon ? 'hide-icons' : ''} ${!showAction ? 'hide-actions' : ''}`}><Preview type={selected.toLowerCase()} interactive /></div>}</div><div className="output-footer"><span><span className={`tiny-dot ${intent}`} />{selected}<span className="slash">/</span>{current.badge}<span className="slash">/</span>{variant}</span><span><CheckCircleIcon /> WCAG AA compliant</span></div></div></div></section>
