@@ -0,0 +1,36 @@
+import type { FormEvent } from 'react';
+
+// Local types for the experimental browser API; no runtime polyfill required.
+export interface Tool {
+  name: string;
+  description: string;
+  inputSchema: Record<string, unknown>;
+  annotations?: { readOnlyHint: boolean };
+  execute: (args: Record<string, unknown>) => Promise<unknown>;
+}
+export interface ModelContext {
+  registerTool(tool: Tool): void | Promise<void>;
+  unregisterTool(name: string): void;
+}
+export function modelContext() {
+  return (navigator as Navigator & { modelContext?: ModelContext }).modelContext
+    ?? (document as Document & { modelContext?: ModelContext }).modelContext;
+}
+
+export function respondToAgent(event: FormEvent<HTMLFormElement>, result: Promise<unknown>) {
+  const nativeEvent = event.nativeEvent as SubmitEvent & {
+    agentInvoked?: boolean;
+    respondWith?: (result: Promise<unknown>) => void;
+  };
+  if (nativeEvent.agentInvoked && nativeEvent.respondWith) nativeEvent.respondWith(result);
+}
+
+declare module 'react' {
+  interface FormHTMLAttributes<T> {
+    toolname?: string;
+    tooldescription?: string;
+    toolautosubmit?: string;
+  }
+  interface InputHTMLAttributes<T> { toolparamdescription?: string; }
+  interface SelectHTMLAttributes<T> { toolparamdescription?: string; }
+}
